ProjectALife.DialogueShards["scenes_any_13"] = {
{"s12_mon_downgrade_039","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear",{1,"Probably a trucker two counties over with a bad ground and a big mouth - probably that",2,"Probably",1,"I moved the girl's bed in with ours though, just till it quits"}},
{"s12_mon_gallows_laugh_040","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=funny",{1,"Best conversation I've had in two weeks was with whatever's on channel nine, hahaha",2,"That ain't funny",1,"No, it asked after my mother and I answered it, is the thing - I sat there and answered it"}},
{"s12_mon_predator_finds_041","any",2,"reg=raider,gang,outlaw|tmp=predator|hour=22,4|mood=grim|world=road",{1,"We once picked up voices on a kid's monitor. Clear enough we thought we knew the house",2,"You thought you knew when they slept?",1,"Thought we did. Then heard somebody breathing on the channel",2,"One of yours?",1,"Couldn't tell. We stopped treating voices on a box like a map of somebody else's life"}},
{"s12_mon_elite_procedure_042","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Signal's on forty nine megahertz, kids' toy band, somebody's using baby monitors as a field net",2,"Range?",1,"Two, three hundred yards a hop, which means their units are strung across the whole county in a chain"}},
{"s12_mon_clergy_043","any",2,"reg=rescue|role=rescue_clergy|tmp=seasoned|hour=20,2|mood=sad",{1,"Three families this week have asked me about voices on them little monitors, Brother",2,"What do you tell 'em?",1,"I tell 'em to unplug it and sleep in the same room - I don't tell 'em what I think it is",2,"What do you think it is?",1,"I think I'm a preacher and not an electrician, and that's as far as I'll go tonight"}},
{"s12_mon_two_way_044","any",2,"reg=family|tmp=fresh,seasoned|hour=23,4|mood=fear",{1,"I talked back to it, I said who is this",2,"Lord, and?",1,"It waited about as long as a person waits, then it said my whole name, first, middle and last"}},
{"s12_mon_radio_check_045","any",2,"reg=military,law|tmp=veteran,seasoned|hour=0,5|mood=calm",{1,"Radio check, how do you read",2,"Five by five, there's a second voice under yours, though - under it",1,"Say again",2,"Under yours, saying the same words a beat behind, I'd rather do this face to face at first light"}},
{"s12_mon_no_batteries_046","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear|world=building",{1,"That set in the corner has got no power to it - no wall cord, no battery, nothing",2,"Then it's a paperweight",1,"Then why has the dial light been on since Thursday - go on - look at it from where you're sitting"}},
{"s12_mon_recording_the_house_047","any",3,"reg=law,swat|tmp=seasoned,veteran|hour=16,5|mood=grim|world=vehicle",{1,"Found a monitor taped up inside a light fixture, battery pack, fresh cells, wire run neat",2,"Whose house?",1,"Ours, the one we've been sleeping in for nine days",3,"Nine days",1,"So tonight we talk about the route in the truck with the engine running - not in the house"}},
{"s12_mon_lullaby_048","any",2,"reg=family|tmp=fresh|hour=22,4|mood=sad|world=building",{1,"She sings on that thing to her doll, every night, same little song her mother did",2,"That's alright, ain't it?",1,"It's the best sound in this house, it's also got a second voice in it some nights, and I let it be"}},
{"s12_mon_wont_use_it_049","any",2,"reg=family,civilian|tmp=seasoned|hour=19,23|mood=grim",{1,"I'd sooner sit in the hall all night than put that thing back on",2,"Then sit in the hall, I'll take the first half",1,"Thank you, and don't plug it in to check - don't do that as a kindness to me"}},
{"s12_mon_answer_wrong_q_050","any",2,"reg=civilian,family|tmp=seasoned|hour=23,5|mood=fear|world=door,window",{1,"Did it ever say anything about us? That's all I want to know",2,"It was hot in that room, I had the window up about four inches, that's the thing I keep on about",1,"That ain't what I asked you",2,"No, it ain't - let's go check the door latch"}},
{"s12_mut_count_field_001","any",1,"reg=civilian,family|tmp=seasoned|hour=19,23|mood=fear",{1,"Twenty one, it was twenty yesterday",1,"Twenty one, and I know every one of their faces - that's the part"}},
{"s12_mut_bell_again_002","any",1,"reg=civilian,worker|tmp=seasoned|hour=0,4|mood=fear",{1,"There it goes, two forty, right on the nose",1,"Eleven, same as last night, eleven, and I'm the only one awake for it"}},
{"s12_mut_dont_look_003","any",1,"reg=civilian,family|tmp=fresh|hour=22,3|mood=fear|world=window",{1,"Don't look at the window, don't, just keep folding"}},
{"s12_mut_probably_a_dog_004","any",1,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"Probably a dog, probably somebody's dog got in the corn",1,"Ninety pound dog with a shovel - sure"}},
{"s12_mut_flag_down_005","any",1,"reg=civilian,family|tmp=seasoned|hour=6,9|mood=grim",{1,"Flag's down again, note's gone again",1,"Well, somebody's reading 'em, at least, somebody's reading 'em"}},
{"s12_mut_chairs_006","any",1,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear",{1,"Four plates - three chairs",1,"I keep coming back around to them chairs and I can't get past it"}},
{"s12_mut_not_going_back_007","any",1,"reg=civilian,family|tmp=seasoned|hour=19,1|mood=grim",{1,"I ain't going back in that house, not for water, not for shells, not for nothing",1,"Somebody else can have whatever's in that pantry"}},
{"s12_mut_i_waved_first_008","any",1,"reg=civilian,worker|tmp=seasoned|hour=18,22|mood=fear",{1,"I waved first, that's on me"}},
{"s12_mut_monitor_off_009","any",1,"reg=family|tmp=fresh|hour=23,4|mood=fear",{1,"It's off, I pulled the battery out of it - it's off",1,"So why am I stood in the hall listening to it"}},
{"s12_mut_tracks_row_011","any",1,"reg=family,civilian|tmp=seasoned|hour=6,10|mood=grim",{1,"Raked it flat last night, one print, dead center",1,"Nothing in - nothing out, just the one"}},
{"s12_mut_coffee_warm_012","any",1,"reg=civilian,worker|tmp=seasoned|hour=14,19|mood=fear",{1,"Coffee in the pot was warm, that's all I've got and that's enough"}},
{"s12_mut_talking_to_june_013","any",1,"reg=family,civilian|tmp=seasoned|hour=21,2|mood=sad",{1,"Goodnight, June",1,"Out loud - don't care who hears it"}},
{"s12_mut_chalk_nine_014","any",1,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=grim|world=road",{1,"Ones and twos the whole street, and then a nine",1,"Nine, in a house that's got two bedrooms, somebody wrote that down for a reason"}},
{"s12_mut_wind_dont_count_015","any",1,"reg=civilian,family|tmp=seasoned|hour=0,5|mood=fear|world=wind",{1,"Wind, it's the wind in the steeple, that's all it is",1,"Wind don't count to six and quit - but alright, it's the wind"}},
{"s12_mut_towel_folded_016","any",1,"reg=civilian,worker|tmp=seasoned|hour=12,18|mood=fear",{1,"Folded twice, hung dry, on a nail, in a barn full of flies",1,"Nope, nope, I'm done with that barn"}},
{"s12_mut_didnt_blink_017","any",1,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear",{1,"Hour and a half and not one blink",1,"And I sat there and passed him the cup like a fool"}},
{"s12_mut_note_we_know_018","any",1,"reg=civilian,family|tmp=seasoned|hour=21,3|mood=fear",{1,"Two words under mine - we know",1,"We - not I, that's the word that's got me up"}},
{"s12_mut_porch_light_019","any",1,"reg=family,civilian|tmp=seasoned|hour=22,4|mood=sad|world=building,generator",{1,"Generator can't spare the porch light",1,"I'm going to keep it on anyway, he'd come up the drive from that side"}},
{"s12_mut_check_the_latch_021","any",1,"reg=civilian,family|tmp=fresh|hour=23,4|mood=fear",{1,"Latched, I latched it",1,"I'll go look one more time and then I'll sit down - one more time"}},
{"s12_mut_bus_aint_come_022","any",1,"reg=family,civilian|tmp=seasoned|hour=15,18|mood=sad|world=vehicle",{1,"Four thirty, there they go, out to the end of the drive",1,"Bus ain't come since the sixth, boys, bus ain't coming"}},
{"s12_mut_saw_quit_023","any",1,"reg=worker,civilian|tmp=seasoned|hour=6,11|mood=grim",{1,"Saw quit this morning",1,"Two days I wanted it to quit, and now I want it back on - look at me"}},
{"s12_mut_law_log_024","any",1,"reg=law|tmp=seasoned,veteran|hour=1,5|mood=calm",{1,"Front room clear - rest of the residence, no entry",1,"That's all that's going in the log and whoever reads it can come ask me"}},
{"s12_mut_military_bearing_025","any",1,"reg=military,elite|tmp=veteran|hour=0,5|mood=calm",{1,"Bell, church type, eleven strikes, zero two forty - third night",1,"Logging it unknown, nobody walks to it"}},
{"s12_mut_i_answered_it_026","any",1,"reg=civilian,worker|tmp=seasoned|hour=1,5|mood=fear",{1,"It asked after my mother and I answered it",1,"Sat right here with the mic in my hand and answered it like a neighbor"}},
{"s12_mut_glass_on_wood_027","any",1,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=fear",{1,"Four seconds, a glass going down on wood - over and over",1,"I should have left it playing, I don't know why I think that, but I do"}},
{"s12_mut_no_flies_028","any",1,"reg=rescue,law|tmp=seasoned|hour=10,17|mood=grim",{1,"Week in that ditch in this heat and not one fly on it",1,"I'll walk the long way home, it's only a half mile"}},
{"s12_mut_hens_029","any",1,"reg=family,worker|tmp=seasoned|hour=6,10|mood=grim|world=door",{1,"Come on out, door's open, feed's down - come on",1,"Fine, you know something I don't - stay up there"}},
{"s12_mut_gate_swings_in_030","any",1,"reg=civilian,worker|tmp=seasoned|hour=12,19|mood=grim",{1,"Hinges on the inside, gate swings in",1,"You got to ask yourself who they built that for"}},
{"s12_mut_wrong_season_031","any",1,"reg=civilian,family|tmp=seasoned|hour=21,2|mood=fear|world=building,summer",{1,"Christmas lights on a porch out Echo Creek - blinking - in summer"}},
{"s12_mut_pager_032","any",1,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=funny",{1,"Going off again, somebody wants me bad",1,"I'd call you back, friend, if a phone in this county did anything but sit there"}},
{"s12_mut_count_buried_033","any",1,"reg=civilian,family|tmp=seasoned|hour=19,23|mood=sad",{1,"Four, I've put four in the ground since the sixth",1,"I'm saying it out loud so the number's somewhere besides my head"}},
{"s12_mut_two_plates_034","any",1,"reg=family,civilian|tmp=seasoned|hour=17,21|mood=sad",{1,"Two plates, every night, two plates",1,"And then I put one back, every night I put one back"}},
{"s12_mut_cellar_smell_035","any",1,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear|world=building",{1,"Cellar smell at the mailbox, ten foot either way and it's gone",1,"Now what in the world puts a smell in one spot and not the next"}},
{"s12_mut_i_shut_the_door_036","any",1,"reg=law,swat|tmp=veteran|hour=22,4|mood=grim|world=door",{1,"Carpet pulled up and folded like a flag",1,"I shut the door, that's my report, and that's all it's ever going to say"}},
{"s12_mut_predator_walks_away_037","any",1,"reg=raider,outlaw,prison|tmp=predator|hour=21,4|mood=grim|world=building",{1,"Full pantry in there and I walked out over a bathtub full of shoes",1,"Laces all tied together - every pair, whoever done that has got time to spare"}},
{"s12_mut_i_hollered_twice_038","any",1,"reg=civilian,family|tmp=fresh|hour=20,2|mood=fear",{1,"I hollered twice",1,"Then I quit hollering, 'cause I got to thinking about what might answer"}},
{"s12_mut_swept_glass_039","any",1,"reg=civilian,worker|tmp=seasoned|hour=13,19|mood=fear",{1,"Little pile of glass in the corner, broom stood up beside it",1,"Somebody's keeping house in there, and it ain't me and it ain't you"}},
{"s12_mut_road_was_moving_040","any",1,"reg=civilian,worker|tmp=seasoned|hour=7,12|mood=fear|world=stairs,road",{1,"The road was moving, not on it - the road was",1,"I come down that ladder faster than I went up"}},
{"s12_mut_bell_count_tally_041","any",1,"reg=civilian,family|tmp=seasoned|hour=23,5|mood=fear|world=door",{1,"Twelve Sunday - thirteen Monday, fourteen last night",1,"I've got it all on the doorframe in pencil, fifteen tonight, if it holds"}},
{"s12_mut_name_on_lid_042","any",1,"reg=family|tmp=fresh|hour=20,1|mood=fear",{1,"The baby's name is on the inside of our mailbox lid",1,"We never told nobody out here the baby's name, not one soul"}},
{"s12_mut_verna_left_hand_043","any",1,"reg=civilian,family|tmp=seasoned|hour=17,21|mood=fear",{1,"Waving with the left",1,"That woman ain't had a left since seventy six, I ain't blind and I ain't crazy"}},
{"s12_mut_i_moved_my_bedroll_044","any",1,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear",{1,"Probably nothing, probably nothing at all",1,"I moved my bedroll though"}},
{"s12_mut_worms_in_fridge_045","any",1,"reg=family,civilian|tmp=seasoned|hour=18,22|mood=sad|world=building",{1,"Told the boy we'd go fishing Saturday, soon as this quit",1,"Worms are still in the fridge, fridge don't work either"}},
{"s12_mut_burn_the_envelopes_046","any",1,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=grim",{1,"Burnt to the stamp and no further, every one of 'em",1,"You try that, you go on and try burning an envelope to the stamp on purpose"}},
{"s12_mut_clock_wound_047","any",1,"reg=civilian,worker|tmp=seasoned|hour=14,20|mood=fear",{1,"Wound, and within a minute of right",1,"So somebody stood in that front room this week with a key in their hand"}},
{"s12_mut_i_am_going_at_noon_048","any",1,"reg=civilian,family|tmp=seasoned|hour=6,11|mood=calm",{1,"Noon, I'll go at noon, with the light straight down and no shadow in that hall",1,"And I'll take Roscoe, and if Roscoe won't go in, then neither will I"}},
{"s12_mut_kid_counts_049","any",1,"reg=family|tmp=fresh|hour=21,1|mood=sad",{1,"He counts along with it under the covers - every strike",1,"Says if somebody don't count it, nobody'll know, eight years old"}},
{"s12_mut_flat_close_050","any",1,"reg=civilian,worker|tmp=seasoned|hour=5,9|mood=calm",{1,"And then it got light out, and we left, that's all that happened"}},
{"s12_mut_eyes_front_051","any",1,"reg=civilian,family|tmp=seasoned|hour=17,21|mood=grim",{1,"Eyes front - don't look at the porches - eyes front"}},
{"s12_mut_dial_light_052","any",1,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear",{1,"No cord, no battery",1,"And that little dial light's been on since Thursday, I've quit looking at it"}},
{"s12_mut_i_drank_it_053","any",1,"reg=family,civilian|tmp=fresh|hour=19,23|mood=fear|world=summer",{1,"A cold RC, in the box, in summer",1,"And I drank it, that's the thing that's going to keep me up - I drank it"}},
{"s12_mut_gentleman_054","any",1,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=fear",{1,"We call him the gentleman, makes it easier to say at the table",1,"That's all it is, a word so the kids can eat their supper"}},
{"s12_mut_i_finished_his_truck_055","any",1,"reg=worker,civilian|tmp=seasoned|hour=16,21|mood=sad|world=vehicle",{1,"He was halfway through that truck when it happened, I finished it",1,"Took me a week 'cause I kept turning round to ask him what come next"}},
{"s12_mut2_same_mower_001","any",1,"reg=civilian,worker|tmp=seasoned|hour=10,17|mood=fear|world=road",{1,"Third time past that turned over mower, same mower, same ditch",1,"And that road is straight as a rifle barrel, we wasn't lost"}},
{"s12_mut2_six_oclock_woman_002","any",1,"reg=civilian,family|tmp=seasoned|hour=17,20|mood=fear|world=fence",{1,"Six o'clock, there she goes",1,"Eleven evenings and she has never once turned her head at this fence"}},
{"s12_mut2_cat_at_stairs_003","any",1,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=fear|world=door",{1,"Get down from there, go on, get",1,"Nine nails I put in that door - nine - sit somewhere else, cat"}},
{"s12_mut2_knock_no_steps_004","any",1,"reg=civilian,worker|tmp=seasoned|hour=0,4|mood=fear",{1,"Three knocks, no steps before it, no steps after",1,"That floor tells on everybody, it didn't tell on that"}},
{"s12_mut2_boy_in_the_tent_005","any",1,"reg=family|tmp=fresh,seasoned|hour=22,4|mood=fear",{1,"He's in the tent, I just looked at him",1,"So that wasn't my boy calling me from the water, then... he's right there asleep"}},
{"s12_mut2_practicing_my_name_006","any",1,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"Put my name in every sentence, every single one",1,"Like somebody getting used to how it sits in the mouth"}},
{"s12_mut2_hum_follows_007","any",1,"reg=worker,civilian|tmp=seasoned|hour=19,1|mood=fear",{1,"Four stops, key out every time",1,"And it come with me on all four - alright, I'm saying it out loud now, so that's done"}},
{"s12_mut2_town_at_ten_mile_008","any",1,"reg=civilian,worker|tmp=seasoned|hour=19,23|mood=grim",{1,"Stood on that ridge and heard a whole town, not a word of it",1,"Just the shape of a town making noise, ten mile off"}},
{"s12_mut2_lights_block_by_block_010","any",1,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=fear",{1,"North to south, even time between each one",1,"Grid don't drop like that, something was walking it"}},
{"s12_mut2_half_second_011","any",1,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=fear",{1,"Half a second late, every answer, same gap",1,"Like there was somebody in between, I'll not have him at this fire again"}},
{"s12_mut2_he_fixed_his_face_012","any",1,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=grim",{1,"I told him my brother was gone and he smiled",1,"Then he fixed it, I watched him fix his own face, that's a thing I can't unsee"}},
{"s12_mut2_asked_after_my_dog_013","any",1,"reg=civilian,family|tmp=seasoned|hour=18,23|mood=fear",{1,"Called Sadie by her name, right there at the gate, like he'd fed her",1,"I've been back through that whole talk four times, I never once said I had a dog"}},
{"s12_mut2_stops_when_i_stop_014","any",1,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"I stop, it stops, I walk, it walks",1,"Done that four times, fourth time I quit testing and run"}},
{"s12_mut2_cattle_corner_015","any",1,"reg=worker,family|tmp=seasoned|hour=6,11|mood=grim",{1,"Gate's wide open, girls - walk on out if you want",1,"No? Thirty head bunched in a corner with the gate open - alright"}},
{"s12_mut2_kennel_016","any",1,"reg=civilian,worker|tmp=seasoned|hour=11,18|mood=grim|world=door",{1,"Twelve runs, doors open, no dogs, no mess, no smell",1,"Twelve, I counted 'em twice because I wanted to be wrong about the twelve"}},
{"s12_mut2_pigeon_dust_017","any",1,"reg=civilian,worker|tmp=seasoned|hour=14,20|mood=fear",{1,"Inch of pigeon mess on that steeple floor, not a mark in it",1,"So nobody's been up there, which is worse, and I know it's worse"}},
{"s12_mut2_bell_pin_018","any",1,"reg=worker|tmp=seasoned|hour=19,23|mood=grim",{1,"I hung that yoke in eighty four, there's a pin has to come out for it to swing",1,"Somebody's pulling a pin the size of my thumb, every night, in the dark - that's a person"}},
{"s12_mut2_four_cans_019","any",1,"reg=civilian,family|tmp=seasoned|hour=8,13|mood=grim",{1,"Ripe ones gone, green ones left on the vine",1,"That ain't hunger, hunger takes the green ones too"}},
{"s12_mut2_watered_garden_020","any",1,"reg=family,civilian|tmp=seasoned|hour=6,10|mood=fear",{1,"Rows are wet, ain't rained since Sunday",1,"That's a lot of buckets up a hill for somebody else's beans"}},
{"s12_mut2_weeds_in_a_pile_021","any",1,"reg=family,civilian|tmp=seasoned|hour=7,12|mood=fear",{1,"Pulled and laid in a pile at the end of the row - neat",1,"I'd say thank you if I knew which way to holler it"}},
{"s12_mut2_scarecrow_022","any",1,"reg=family,civilian|tmp=seasoned|hour=7,12|mood=fear",{1,"Fifteen foot closer than where I set it, new hole, tamped down",1,"Whoever moved it brought a shovel, you bring a shovel when you mean to stay"}},
{"s12_mut2_minnows_024","any",1,"reg=worker,civilian|tmp=seasoned|hour=10,17|mood=grim|world=water",{1,"Stood in that creek to my knees and nothing moved",1,"First time in fifty years I've been in that water and had it be still"}},
{"s12_mut2_deer_stand_025","any",1,"reg=civilian,worker|tmp=seasoned|hour=5,9|mood=fear",{1,"Six butts lined up on the rail of my own stand",1,"And that stand looks at my back door, not at a deer trail - somebody sat up there and watched"}},
{"s12_mut2_backwards_prints_026","any",1,"reg=worker,civilian|tmp=seasoned|hour=6,11|mood=grim",{1,"Heel to toe backwards, all the way to the pump",1,"Somebody walked out backwards, that's the sensible answer and I'm keeping it"}},
{"s12_mut2_ninety_pound_027","any",1,"reg=worker|tmp=seasoned,veteran|hour=7,12|mood=fear",{1,"I've read sign thirty years, hogs, deer, men",1,"Depth on them prints says about ninety pound, and the stride says six foot - figure that"}},
{"s12_mut2_i_answered_the_board_028","any",1,"reg=law|tmp=seasoned|hour=1,5|mood=grim",{1,"Prowler call, written on the board in the night - neat printing",1,"Third one from an address nobody's living at, I'm going to stop going to that address"}},
{"s12_mut2_our_boot_tread_029","any",1,"reg=military,elite|tmp=veteran|hour=0,5|mood=calm",{1,"Our tread - our size, inside the wire, and we were never on that side",1,"Pattern changes tonight and it changes without being said on the radio"}},
{"s12_mut2_trainee_030","any",1,"reg=military|role=soldier_green|tmp=fresh|hour=1,5|mood=fear",{1,"I'm not going to be the only one that's seen 'em - I'm not doing that",1,"I'll wake him up, he can be mad at me - being mad is fine"}},
{"s12_mut2_delta_note_031","any",1,"reg=elite|role=elite_delta|tmp=veteran|hour=0,5|mood=calm",{1,"One set in, one set out, four hours apart by the dew",1,"Whoever it is keeps a schedule, we break the schedule, we find out who keeps it"}},
{"s12_mut2_clergy_032","any",1,"reg=rescue|role=rescue_clergy|tmp=seasoned|hour=21,3|mood=sad",{1,"Three families this week, all asking me about voices on them little monitors",1,"I tell 'em unplug it and sleep in one room - I don't tell 'em the rest of what I think"}},
{"s12_mut2_medic_033","any",1,"reg=rescue|role=rescue_medical|tmp=seasoned|hour=19,1|mood=calm",{1,"Pulse fine, pupils fine, answers everything",1,"Same tone for his name as for where it hurts - I'll work on him outside, in the light"}},
{"s12_mut2_predator_034","any",1,"reg=raider,gang|tmp=predator|hour=22,4|mood=grim|world=road",{1,"Tended garden and nobody in the house, two nights I watched it",1,"Whoever tends it can keep it, we'll work the other road"}},
